// resolveO2OJoins inspects FieldOptions and returns JOIN descriptors for each O2O relationship.
// Returns nil if no O2O relationships are requested.
func (c *eventClient) resolveO2OJoins(d sql.Dialect, fo *EventFieldOptions) []sql.JoinClause {
	if fo == nil {
		return nil
	}
	var joins []sql.JoinClause
	if fo.Note != nil {
		joins = append(joins, sql.JoinClause{
			Table: sql.Table{Schema: "audit", Name: "notes"},
			Alias: "n",
			On:    fmt.Sprintf("n.%s = e.%s", d.QuoteIdentifier("event_id"), d.QuoteIdentifier("id")),
			// The NULL-detection below reads the target's PK off the scanned
			// row, so the join carries it even when FieldOptions did not ask
			// for it — an unselected PK reads as a LEFT JOIN miss.
			Columns: unionColumns(fo.Note.Columns(), "id"),
		})
		if fo.Note.Author != nil {
			joins = append(joins, sql.JoinClause{
				Table: sql.Table{Schema: "public", Name: "users"},
				Alias: "a",
				On:    fmt.Sprintf("a.%s = n.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("user_id")),
				// The NULL-detection below reads the target's PK off the scanned
				// row, so the join carries it even when FieldOptions did not ask
				// for it — an unselected PK reads as a LEFT JOIN miss.
				Columns: unionColumns(fo.Note.Author.Columns(), "id"),
			})
			if fo.Note.Author.Profile != nil {
				joins = append(joins, sql.JoinClause{
					Table: sql.Table{Schema: "public", Name: "profiles"},
					Alias: "p",
					On:    fmt.Sprintf("p.%s = a.%s", d.QuoteIdentifier("user_id"), d.QuoteIdentifier("id")),
					// The NULL-detection below reads the target's PK off the scanned
					// row, so the join carries it even when FieldOptions did not ask
					// for it — an unselected PK reads as a LEFT JOIN miss.
					Columns: unionColumns(fo.Note.Author.Profile.Columns(), "id"),
				})
				if fo.Note.Author.Profile.Users != nil {
					joins = append(joins, sql.JoinClause{
						Table: sql.Table{Schema: "public", Name: "users"},
						Alias: "u",
						On:    fmt.Sprintf("u.%s = p.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("user_id")),
						// The NULL-detection below reads the target's PK off the scanned
						// row, so the join carries it even when FieldOptions did not ask
						// for it — an unselected PK reads as a LEFT JOIN miss.
						Columns: unionColumns(fo.Note.Author.Profile.Users.Columns(), "id"),
					})
					if fo.Note.Author.Profile.Users.Profile != nil {
						joins = append(joins, sql.JoinClause{
							Table: sql.Table{Schema: "public", Name: "profiles"},
							Alias: "p2",
							On:    fmt.Sprintf("p2.%s = u.%s", d.QuoteIdentifier("user_id"), d.QuoteIdentifier("id")),
							// The NULL-detection below reads the target's PK off the scanned
							// row, so the join carries it even when FieldOptions did not ask
							// for it — an unselected PK reads as a LEFT JOIN miss.
							Columns: unionColumns(fo.Note.Author.Profile.Users.Profile.Columns(), "id"),
						})
						if fo.Note.Author.Profile.Users.Profile.Users != nil {
							joins = append(joins, sql.JoinClause{
								Table: sql.Table{Schema: "public", Name: "users"},
								Alias: "u2",
								On:    fmt.Sprintf("u2.%s = p2.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("user_id")),
								// The NULL-detection below reads the target's PK off the scanned
								// row, so the join carries it even when FieldOptions did not ask
								// for it — an unselected PK reads as a LEFT JOIN miss.
								Columns: unionColumns(fo.Note.Author.Profile.Users.Profile.Users.Columns(), "id"),
							})
						}
					}
				}
			}
		}
	}
	if fo.SourceNote != nil {
		joins = append(joins, sql.JoinClause{
			Table: sql.Table{Schema: "public", Name: "notes"},
			Alias: "s",
			On:    fmt.Sprintf("s.%s = e.%s", d.QuoteIdentifier("source_event_id"), d.QuoteIdentifier("id")),
			// The NULL-detection below reads the target's PK off the scanned
			// row, so the join carries it even when FieldOptions did not ask
			// for it — an unselected PK reads as a LEFT JOIN miss.
			Columns: unionColumns(fo.SourceNote.Columns(), "id"),
		})
	}
	return joins
}

// scanEventsWithOneToOneJoins scans rows from a LEFT JOIN query into
// Event entities with O2O relationships populated.
// Routes columns by alias prefix and detects LEFT JOIN misses via NULL PK detection.
func scanEventsWithOneToOneJoins(rows database.Rows, columns []string) ([]*Event, error) {
	var result []*Event
	for rows.Next() {
		e := &Event{}
		a := &PublicUser{}
		aHasData := false
		n := &AuditNote{}
		nHasData := false
		p := &Profile{}
		pHasData := false
		p2 := &Profile{}
		p2HasData := false
		s := &PublicNote{}
		sHasData := false
		u := &PublicUser{}
		uHasData := false
		u2 := &PublicUser{}
		u2HasData := false

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "e.id":
				targets[idx] = &e.ID
			case "e.name":
				targets[idx] = &e.Name
			case "e.payload":
				targets[idx] = &e.Payload
			case "e.created_at":
				targets[idx] = &e.CreatedAt
			case "a.id":
				targets[idx] = database.NullScan(&a.ID)
				aHasData = true
			case "a.email":
				targets[idx] = database.NullScan(&a.Email)
			case "a.name":
				targets[idx] = database.NullScan(&a.Name)
			case "a.role":
				targets[idx] = database.NullScan(&a.Role)
			case "a.tags":
				targets[idx] = &a.Tags
			case "a.metadata":
				targets[idx] = &a.Metadata
			case "a.created_at":
				targets[idx] = database.NullScan(&a.CreatedAt)
			case "a.updated_at":
				targets[idx] = &a.UpdatedAt
			case "n.id":
				targets[idx] = database.NullScan(&n.ID)
				nHasData = true
			case "n.user_id":
				targets[idx] = database.NullScan(&n.UserID)
			case "n.event_id":
				targets[idx] = &n.EventID
			case "n.severity":
				targets[idx] = database.NullScan(&n.Severity)
			case "p.id":
				targets[idx] = database.NullScan(&p.ID)
				pHasData = true
			case "p.user_id":
				targets[idx] = database.NullScan(&p.UserID)
			case "p.bio":
				targets[idx] = &p.Bio
			case "p.avatar_url":
				targets[idx] = &p.AvatarURL
			case "p.address":
				targets[idx] = &p.Address
			case "p.scores":
				targets[idx] = &p.Scores
			case "p.created_at":
				targets[idx] = database.NullScan(&p.CreatedAt)
			case "p2.id":
				targets[idx] = database.NullScan(&p2.ID)
				p2HasData = true
			case "p2.user_id":
				targets[idx] = database.NullScan(&p2.UserID)
			case "p2.bio":
				targets[idx] = &p2.Bio
			case "p2.avatar_url":
				targets[idx] = &p2.AvatarURL
			case "p2.address":
				targets[idx] = &p2.Address
			case "p2.scores":
				targets[idx] = &p2.Scores
			case "p2.created_at":
				targets[idx] = database.NullScan(&p2.CreatedAt)
			case "s.id":
				targets[idx] = database.NullScan(&s.ID)
				sHasData = true
			case "s.user_id":
				targets[idx] = database.NullScan(&s.UserID)
			case "s.source_event_id":
				targets[idx] = &s.SourceEventID
			case "s.body":
				targets[idx] = database.NullScan(&s.Body)
			case "u.id":
				targets[idx] = database.NullScan(&u.ID)
				uHasData = true
			case "u.email":
				targets[idx] = database.NullScan(&u.Email)
			case "u.name":
				targets[idx] = database.NullScan(&u.Name)
			case "u.role":
				targets[idx] = database.NullScan(&u.Role)
			case "u.tags":
				targets[idx] = &u.Tags
			case "u.metadata":
				targets[idx] = &u.Metadata
			case "u.created_at":
				targets[idx] = database.NullScan(&u.CreatedAt)
			case "u.updated_at":
				targets[idx] = &u.UpdatedAt
			case "u2.id":
				targets[idx] = database.NullScan(&u2.ID)
				u2HasData = true
			case "u2.email":
				targets[idx] = database.NullScan(&u2.Email)
			case "u2.name":
				targets[idx] = database.NullScan(&u2.Name)
			case "u2.role":
				targets[idx] = database.NullScan(&u2.Role)
			case "u2.tags":
				targets[idx] = &u2.Tags
			case "u2.metadata":
				targets[idx] = &u2.Metadata
			case "u2.created_at":
				targets[idx] = database.NullScan(&u2.CreatedAt)
			case "u2.updated_at":
				targets[idx] = &u2.UpdatedAt
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan event with joins: %w", err)
		}

		// NULL detection — assign deepest chain first, then parents
		if u2HasData && u2.ID != (uuid.UUID{}) {
			p2.Users = u2
		} else {
			p2.Users = nil
		}
		if uHasData && u.ID != (uuid.UUID{}) {
			p.Users = u
		} else {
			p.Users = nil
		}
		if sHasData && s.ID != (uuid.UUID{}) {
			e.SourceNote = s
		} else {
			e.SourceNote = nil
		}
		if p2HasData && p2.ID != (uuid.UUID{}) {
			u.Profile = p2
		} else {
			u.Profile = nil
		}
		if pHasData && p.ID != (uuid.UUID{}) {
			a.Profile = p
		} else {
			a.Profile = nil
		}
		if nHasData && n.ID != 0 {
			e.Note = n
		} else {
			e.Note = nil
		}
		if aHasData && a.ID != (uuid.UUID{}) {
			n.Author = a
		} else {
			n.Author = nil
		}

		result = append(result, e)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate event rows: %w", err)
	}
	return result, nil
}

