// resolveO2OJoins inspects FieldOptions and returns JOIN descriptors for each O2O relationship.
// Returns nil if no O2O relationships are requested.
func (c *auditNoteClient) resolveO2OJoins(d sql.Dialect, fo *AuditNoteFieldOptions) []sql.JoinClause {
	if fo == nil {
		return nil
	}
	var joins []sql.JoinClause
	if fo.Author != nil {
		joins = append(joins, sql.JoinClause{
			Table: sql.Table{Schema: "public", Name: "users"},
			Alias: "a2",
			On:    fmt.Sprintf("a2.%s = a.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("user_id")),
			// The NULL-detection below reads the target's PK off the scanned
			// row, so the join carries it even when FieldOptions did not ask
			// for it — an unselected PK reads as a LEFT JOIN miss.
			Columns: unionColumns(fo.Author.Columns(), "id"),
		})
		if fo.Author.Profile != nil {
			joins = append(joins, sql.JoinClause{
				Table: sql.Table{Schema: "public", Name: "profiles"},
				Alias: "p",
				On:    fmt.Sprintf("p.%s = a2.%s", d.QuoteIdentifier("user_id"), d.QuoteIdentifier("id")),
				// The NULL-detection below reads the target's PK off the scanned
				// row, so the join carries it even when FieldOptions did not ask
				// for it — an unselected PK reads as a LEFT JOIN miss.
				Columns: unionColumns(fo.Author.Profile.Columns(), "id"),
			})
			if fo.Author.Profile.Users != nil {
				joins = append(joins, sql.JoinClause{
					Table: sql.Table{Schema: "public", Name: "users"},
					Alias: "u",
					On:    fmt.Sprintf("u.%s = p.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("user_id")),
					// The NULL-detection below reads the target's PK off the scanned
					// row, so the join carries it even when FieldOptions did not ask
					// for it — an unselected PK reads as a LEFT JOIN miss.
					Columns: unionColumns(fo.Author.Profile.Users.Columns(), "id"),
				})
				if fo.Author.Profile.Users.Profile != nil {
					joins = append(joins, sql.JoinClause{
						Table: sql.Table{Schema: "public", Name: "profiles"},
						Alias: "p2",
						On:    fmt.Sprintf("p2.%s = u.%s", d.QuoteIdentifier("user_id"), d.QuoteIdentifier("id")),
						// The NULL-detection below reads the target's PK off the scanned
						// row, so the join carries it even when FieldOptions did not ask
						// for it — an unselected PK reads as a LEFT JOIN miss.
						Columns: unionColumns(fo.Author.Profile.Users.Profile.Columns(), "id"),
					})
					if fo.Author.Profile.Users.Profile.Users != nil {
						joins = append(joins, sql.JoinClause{
							Table: sql.Table{Schema: "public", Name: "users"},
							Alias: "u2",
							On:    fmt.Sprintf("u2.%s = p2.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("user_id")),
							// The NULL-detection below reads the target's PK off the scanned
							// row, so the join carries it even when FieldOptions did not ask
							// for it — an unselected PK reads as a LEFT JOIN miss.
							Columns: unionColumns(fo.Author.Profile.Users.Profile.Users.Columns(), "id"),
						})
						if fo.Author.Profile.Users.Profile.Users.Profile != nil {
							joins = append(joins, sql.JoinClause{
								Table: sql.Table{Schema: "public", Name: "profiles"},
								Alias: "p3",
								On:    fmt.Sprintf("p3.%s = u2.%s", d.QuoteIdentifier("user_id"), d.QuoteIdentifier("id")),
								// The NULL-detection below reads the target's PK off the scanned
								// row, so the join carries it even when FieldOptions did not ask
								// for it — an unselected PK reads as a LEFT JOIN miss.
								Columns: unionColumns(fo.Author.Profile.Users.Profile.Users.Profile.Columns(), "id"),
							})
						}
					}
				}
			}
		}
	}
	return joins
}

// scanAuditNotesWithOneToOneJoins scans rows from a LEFT JOIN query into
// AuditNote entities with O2O relationships populated.
// Routes columns by alias prefix and detects LEFT JOIN misses via NULL PK detection.
func scanAuditNotesWithOneToOneJoins(rows database.Rows, columns []string) ([]*AuditNote, error) {
	var result []*AuditNote
	for rows.Next() {
		a := &AuditNote{}
		a2 := &PublicUser{}
		a2HasData := false
		p := &Profile{}
		pHasData := false
		p2 := &Profile{}
		p2HasData := false
		p3 := &Profile{}
		p3HasData := false
		u := &PublicUser{}
		uHasData := false
		u2 := &PublicUser{}
		u2HasData := false

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "a.id":
				targets[idx] = &a.ID
			case "a.user_id":
				targets[idx] = &a.UserID
			case "a.event_id":
				targets[idx] = &a.EventID
			case "a.severity":
				targets[idx] = &a.Severity
			case "a2.id":
				targets[idx] = database.NullScan(&a2.ID)
				a2HasData = true
			case "a2.email":
				targets[idx] = database.NullScan(&a2.Email)
			case "a2.name":
				targets[idx] = database.NullScan(&a2.Name)
			case "a2.role":
				targets[idx] = database.NullScan(&a2.Role)
			case "a2.tags":
				targets[idx] = &a2.Tags
			case "a2.metadata":
				targets[idx] = &a2.Metadata
			case "a2.created_at":
				targets[idx] = database.NullScan(&a2.CreatedAt)
			case "a2.updated_at":
				targets[idx] = &a2.UpdatedAt
			case "p.id":
				targets[idx] = database.NullScan(&p.ID)
				pHasData = true
			case "p.user_id":
				targets[idx] = database.NullScan(&p.UserID)
			case "p.bio":
				targets[idx] = &p.Bio
			case "p.avatar_url":
				targets[idx] = &p.AvatarURL
			case "p.address":
				targets[idx] = &p.Address
			case "p.scores":
				targets[idx] = &p.Scores
			case "p.created_at":
				targets[idx] = database.NullScan(&p.CreatedAt)
			case "p2.id":
				targets[idx] = database.NullScan(&p2.ID)
				p2HasData = true
			case "p2.user_id":
				targets[idx] = database.NullScan(&p2.UserID)
			case "p2.bio":
				targets[idx] = &p2.Bio
			case "p2.avatar_url":
				targets[idx] = &p2.AvatarURL
			case "p2.address":
				targets[idx] = &p2.Address
			case "p2.scores":
				targets[idx] = &p2.Scores
			case "p2.created_at":
				targets[idx] = database.NullScan(&p2.CreatedAt)
			case "p3.id":
				targets[idx] = database.NullScan(&p3.ID)
				p3HasData = true
			case "p3.user_id":
				targets[idx] = database.NullScan(&p3.UserID)
			case "p3.bio":
				targets[idx] = &p3.Bio
			case "p3.avatar_url":
				targets[idx] = &p3.AvatarURL
			case "p3.address":
				targets[idx] = &p3.Address
			case "p3.scores":
				targets[idx] = &p3.Scores
			case "p3.created_at":
				targets[idx] = database.NullScan(&p3.CreatedAt)
			case "u.id":
				targets[idx] = database.NullScan(&u.ID)
				uHasData = true
			case "u.email":
				targets[idx] = database.NullScan(&u.Email)
			case "u.name":
				targets[idx] = database.NullScan(&u.Name)
			case "u.role":
				targets[idx] = database.NullScan(&u.Role)
			case "u.tags":
				targets[idx] = &u.Tags
			case "u.metadata":
				targets[idx] = &u.Metadata
			case "u.created_at":
				targets[idx] = database.NullScan(&u.CreatedAt)
			case "u.updated_at":
				targets[idx] = &u.UpdatedAt
			case "u2.id":
				targets[idx] = database.NullScan(&u2.ID)
				u2HasData = true
			case "u2.email":
				targets[idx] = database.NullScan(&u2.Email)
			case "u2.name":
				targets[idx] = database.NullScan(&u2.Name)
			case "u2.role":
				targets[idx] = database.NullScan(&u2.Role)
			case "u2.tags":
				targets[idx] = &u2.Tags
			case "u2.metadata":
				targets[idx] = &u2.Metadata
			case "u2.created_at":
				targets[idx] = database.NullScan(&u2.CreatedAt)
			case "u2.updated_at":
				targets[idx] = &u2.UpdatedAt
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan note with joins: %w", err)
		}

		// NULL detection — assign deepest chain first, then parents
		if u2HasData && u2.ID != (uuid.UUID{}) {
			p2.Users = u2
		} else {
			p2.Users = nil
		}
		if uHasData && u.ID != (uuid.UUID{}) {
			p.Users = u
		} else {
			p.Users = nil
		}
		if p3HasData && p3.ID != (uuid.UUID{}) {
			u2.Profile = p3
		} else {
			u2.Profile = nil
		}
		if p2HasData && p2.ID != (uuid.UUID{}) {
			u.Profile = p2
		} else {
			u.Profile = nil
		}
		if pHasData && p.ID != (uuid.UUID{}) {
			a2.Profile = p
		} else {
			a2.Profile = nil
		}
		if a2HasData && a2.ID != (uuid.UUID{}) {
			a.Author = a2
		} else {
			a.Author = nil
		}

		result = append(result, a)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate note rows: %w", err)
	}
	return result, nil
}

