// Connection returns a Relay-style cursor-paginated connection of asset_document_links.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *assetDocumentLinkClient) Connection(ctx context.Context, input ConnectionInput[AssetDocumentLinkFilter], opts ...func(*CallOptions[AssetDocumentLinkFieldOptions])) (*Connection[AssetDocumentLink], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection asset_document_links: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableAssetDocumentLinks, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[AssetDocumentLinkFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection asset_document_links count: %w", err)
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeCursor(*input.After)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeCursor(*input.Before)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		assetDocumentLinks, err := c.GetMany(ctx, &GetAssetDocumentLinksInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection asset_document_links: %w", err)
		}

		// Trim extra row and determine page boundaries
		hasMore := len(assetDocumentLinks) > limit
		if hasMore {
			assetDocumentLinks = assetDocumentLinks[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(assetDocumentLinks)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[AssetDocumentLink], len(assetDocumentLinks))
		for i, row := range assetDocumentLinks {
			cursor, err := encodeAssetDocumentLinkCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[AssetDocumentLink]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[AssetDocumentLink]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*Connection[AssetDocumentLink]), nil
}

// encodeAssetDocumentLinkCursor encodes cursor key values as a base64 JSON string.
func encodeAssetDocumentLinkCursor(keys []string, a *AssetDocumentLink) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "asset_id":
			out["asset_id"] = a.AssetID
		case "document_id":
			out["document_id"] = a.DocumentID
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode asset_document_link cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

