// defaultOnlyRowAllColumns is the column list for full-entity reads, sorted for determinism.
var defaultOnlyRowAllColumns = []string{"active", "hits", "id", "label"}

// scanDefaultOnlyRows scans rows into DefaultOnlyRow entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanDefaultOnlyRows(rows database.Rows, columns []string) ([]*DefaultOnlyRow, error) {
	var result []*DefaultOnlyRow
	for rows.Next() {
		d := &DefaultOnlyRow{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "id":
				targets[idx] = &d.ID
			case "label":
				targets[idx] = &d.Label
			case "hits":
				targets[idx] = &d.Hits
			case "active":
				targets[idx] = &d.Active
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan default_only_row: %w", err)
		}

		result = append(result, d)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate default_only_row rows: %w", err)
	}
	return result, nil
}

// Get returns a single default_only_row by primary key with optional field selection.
